// Validate input and build the Overpass query. Mirrors lib/overpass.ts guards.
const b = $input.first().json.body || {};
const lat = Number(b.lat), lon = Number(b.lon), radius = Math.round(Number(b.radius ?? 120));
if (!Number.isFinite(lat) || !Number.isFinite(lon) || lat < -90 || lat > 90 || lon < -180 || lon > 180) throw new Error('bad coordinates');
if (!(radius >= 10 && radius <= 400)) throw new Error('radius must be 10..400');
const keys = ['amenity','shop','tourism','historic','leisure','building','man_made','natural','public_transport','railway'];
const clauses = keys.map(k => `  nwr["${k}"]["name"](around:${radius},${lat.toFixed(6)},${lon.toFixed(6)});`).join('\n');
const query = `[out:json][timeout:20];\n(\n${clauses}\n);\nout center tags 200;`;
return [{ json: { query, lat, lon, locale: ['en','fr','es'].includes(b.locale) ? b.locale : 'en', anchor: b.anchor || '' } }];

// Parse and sanitise, then score landmarks around the point (approach bearing from input, default 0).
const input = $('Build Overpass query').first().json;
const res = $input.first().json;
const elements = Array.isArray(res.elements) ? res.elements.slice(0, 2000) : [];
const clean = s => String(s ?? '').replace(/[\u0000-\u001f\u007f-\u009f\p{Cf}\u2028\u2029<>`{}\[\]]/gu, '').trim().slice(0, 120);
const keys = ['amenity','shop','tourism','historic','leisure','building','man_made','natural','public_transport','railway'];
const R = 6371000, toRad = d => d * Math.PI / 180;
const dist = (a, b) => { const dLat = toRad(b.lat - a.lat), dLon = toRad(b.lon - a.lon); const s = Math.sin(dLat/2)**2 + Math.cos(toRad(a.lat))*Math.cos(toRad(b.lat))*Math.sin(dLon/2)**2; return 2*R*Math.asin(Math.min(1, Math.sqrt(s))); };
const weight = (k, v) => ({'amenity:place_of_worship':1,'amenity:fuel':0.9,'amenity:pharmacy':0.85,'amenity:bank':0.8,'amenity:cafe':0.75,'shop:supermarket':0.85,'leisure:park':0.8,'man_made:tower':0.9,'railway:station':0.9})[k+':'+v] ?? 0.4;
const center = { lat: input.lat, lon: input.lon };
const out = [];
for (const e of elements) {
  if (!e || typeof e !== 'object') continue;
  const tags = e.tags && typeof e.tags === 'object' ? e.tags : {};
  const name = clean(tags.name); if (!name) continue;
  const lat = typeof e.lat === 'number' ? e.lat : e.center?.lat, lon = typeof e.lon === 'number' ? e.lon : e.center?.lon;
  if (!Number.isFinite(lat) || !Number.isFinite(lon)) continue;
  const key = keys.find(k => typeof tags[k] === 'string'); if (!key) continue;
  const value = String(tags[key]).replace(/[^a-z0-9_:-]/gi, '').slice(0, 60);
  const d = dist(center, { lat, lon }); if (d > 120) continue;
  const score = 0.5 * (1 - d / 120) + 0.5 * weight(key, value);
  out.push({ name, key, value, lat, lon, distanceM: Math.round(d), score: Math.round(score * 1000) / 1000 });
}
out.sort((a, b) => b.score - a.score);
const top = out.slice(0, 3);
const phr = { en: ['You are facing ', 'Turn toward '], fr: ['Vous faites face a ', 'Tournez vers '], es: ['Estas mirando hacia ', 'Gira hacia '] }[input.locale];
const card = top.length ? [phr[0] + top[0].name + '.', '1. ' + phr[1] + top[0].name + '.'] : ['[no landmark available; confirm with a person or a photo]'];
return [{ json: { landmarks: out, top, card: card.join('\n'), locale: input.locale } }];
